<?php require 'common.php';if(logged())go('index.php');$error='';
if($_SERVER['REQUEST_METHOD']==='POST') {check_csrf();$ip=substr($_SERVER['REMOTE_ADDR']??'unknown',0,45);$q=db()->prepare('SELECT COUNT(*) FROM login_attempts WHERE ip=? AND attempted_at>DATE_SUB(NOW(),INTERVAL 15 MINUTE)');$q->execute([$ip]);if((int)$q->fetchColumn()>=8){$error='Muitas tentativas. Aguarde 15 minutos.';}else{$email=trim((string)($_POST['email']??''));$pass=(string)($_POST['password']??'');$s=db()->prepare('SELECT id,password_hash FROM users WHERE email=?');$s->execute([$email]);$user=$s->fetch();if($user&&password_verify($pass,$user['password_hash'])){db()->prepare('DELETE FROM login_attempts WHERE ip=?')->execute([$ip]);session_regenerate_id(true);$_SESSION['admin_id']=(int)$user['id'];admin_log('login');go('index.php');}else{db()->prepare('INSERT INTO login_attempts(ip) VALUES(?)')->execute([$ip]);$error='Credenciais inválidas.';}}}
admin_top('Acesso administrativo');?><div class="login"><h2>Entrar na MK3</h2><?php if($error):?><div class="alert"><?=h($error)?></div><?php endif;?><form method="post"><?=token_field()?><label>E-mail<input type="email" name="email" required maxlength="190" autocomplete="username"></label><label>Senha<input type="password" name="password" required autocomplete="current-password"></label><button class="button red">ENTRAR</button></form><p class="fineprint">Acesso exclusivo a responsáveis autorizados pela loja.</p></div><?php admin_bottom(); ?>
